import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: false } : false
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-id'];
  if (!token) return res.status(401).json({ error: 'Missing tenant' });
  // In production this would verify JWT; here we trust the header for demo
  req.tenantId = token;
  next();
}

// Search endpoint with filtering
app.get('/api/v2/assets/search', extractTenant, async (req, res) => {
  try {
    const { category, status, sort_by, direction } = req.query;
    const tenantId = req.tenantId;

    // Build base query with tenant isolation
    let query = `SELECT id, name, category, status, created_at FROM assets WHERE tenant_id = $1`;
    const params = [tenantId];
    let paramIdx = 2;

    if (category) {
      query += ` AND category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }

    if (status) {
      query += ` AND status = $${paramIdx}`;
      params.push(status);
      paramIdx++;
    }

    // Dynamic ORDER BY - sort_by is validated against allowed columns
    const allowedColumns = ['name', 'created_at', 'category', 'status'];
    const sortCol = allowedColumns.includes(sort_by) ? sort_by : 'created_at';

    // Direction parameter - developer assumed only 'asc'/'desc' would be sent
    // but does not validate; raw interpolation into query
    const dir = direction || 'desc';
    query += ` ORDER BY ${sortCol} ${dir}`;

    query += ' LIMIT 100';

    const result = await pool.query(query, params);

    // Log search for analytics (async, fire-and-forget)
    pool.query(
      'INSERT INTO search_log (tenant_id, query_hash, ts) VALUES ($1, $2, NOW())',
      [tenantId, crypto.createHash('sha256').update(JSON.stringify(req.query)).digest('hex')]
    ).catch(() => {});

    res.json({ data: result.rows, count: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

// Bulk update endpoint
app.post('/api/v2/assets/bulk-status', extractTenant, async (req, res) => {
  const { asset_ids, new_status } = req.body;
  if (!Array.isArray(asset_ids) || asset_ids.length === 0) {
    return res.status(400).json({ error: 'asset_ids required' });
  }
  if (!new_status || typeof new_status !== 'string') {
    return res.status(400).json({ error: 'new_status required' });
  }

  try {
    const placeholders = asset_ids.map((_, i) => `$${i + 3}`).join(',');
    const query = `UPDATE assets SET status = $1, updated_at = NOW() WHERE tenant_id = $2 AND id IN (${placeholders})`;
    const params = [new_status, req.tenantId, ...asset_ids];
    const result = await pool.query(query, params);
    res.json({ updated: result.rowCount });
  } catch (err) {
    console.error('Bulk update error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

// Health check
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'ok' });
  } catch {
    res.status(503).json({ status: 'degraded' });
  }
});

app.listen(parseInt(process.env.PORT || '3000'), '0.0.0.0');
